add('REST 응답','정상 응답과 실패 응답 구분',table([['상태 코드','오늘 상품 API에서의 의미'],['200 / 201','조회 성공 / 상품 생성 성공'],['400 / 404','잘못된 입력 / 조회할 상품이 없음'],['500','예상하지 못한 서버 처리 오류']])+call('실패 이유에 맞게 상태와 본문을 함께 정합니다.<br>모든 예외를 400으로 바꾸면 서버 문제까지 입력 오류처럼 보입니다.'),note='이 표는 오늘 상품 API의 응답 설계 기준입니다. 없는 상품의 404는 해당 예외에 대한 매핑을 구현해야 합니다. 프레임워크가 모든 업무 예외를 알아서 400/404로 분류한다고 설명하지 않습니다. HTTP 메서드 전체와 REST 성숙도는 별도 긴 강의로 확장하지 않고 필요한 질문만 연결합니다.')
add('교재 CH 10','유효성 검사와 예외 처리',steps('도메인 객체와 Controller의 입력 검사','전역 예외 핸들러','HTTP 응답 상태 코드와 오류 본문')+call('책의 10장을 함께 보며 검사 위치와 실패 응답을 연결합니다.'),note='도메인 객체 및 컨트롤러 유효성 검사 추가하기, 전역 예외 핸들러 추가하기, HTTP 응답 상태 코드와 바디 순서로 실제 책을 읽습니다. 오늘은 중요 개념과 책의 코드 확인을 중심으로 진행하고 전체 코드를 다시 시연하지 않습니다.')
add('유효성 검사','검사 위치와 책임',table([['위치','확인할 내용'],['요청 DTO','이름·가격의 필수 여부와 입력 형식'],['도메인 객체','유효한 이름·0 이상의 가격 같은 상품 자체의 규칙'],['Service','상품 존재 여부처럼 업무 처리에 필요한 조건']])+call('요청 DTO를 통과한 값도 다른 경로로 들어올 수 있습니다.<br>도메인 객체의 규칙은 HTTP 요청이 없어도 지켜져야 합니다.'),note='외부 입력 검증과 도메인 불변 조건은 목적이 다릅니다. 단순한 중복 제거를 이유로 도메인 검증을 모두 없애지 않습니다. 존재하지 않는 상품 조회는 요청 DTO의 @NotNull 검사로 해결되지 않고 업무 처리 결과에 따라 예외와 응답을 정해야 합니다.')
add('유효성 검사','누락과 0원 구분',table([['값','상품 입력에서 판단할 내용'],['이름 null·빈 문자열·공백','상품명으로 허용하지 않음'],['가격 누락·null','값을 입력하지 않은 상태'],['가격 0 / 음수','무료 상품은 허용 / 음수 가격은 거부']])+call('요청 DTO의 가격은 Integer로 받아 누락과 0원을 구분합니다.<br>앞뒤 공백 정리와 필수값 검사는 별도로 결정합니다.'),note='primitive int는 기본값 0이므로 누락과 명시적인 0을 구분하기 어렵습니다. Integer로 null을 표현하고 @NotNull로 필수 조건을 둡니다. 도메인에는 유효한 값만 전달합니다. @NotBlank는 문자열을 trim해서 바꿔주는 기능이 아닙니다. 교재와 기존 Product의 앞뒤 공백 정리 규칙을 보존합니다.')
add('유효성 검사','제약 조건과 @Valid',table([['표시할 곳','오늘 코드에서 확인할 내용'],['이름 · @NotBlank','null·빈 문자열·공백뿐인 문자열 거부'],['가격 · @NotNull + @Min(0)','누락 거부와 0 이상 조건을 함께 적용'],['Controller 인자 · @Valid','요청 DTO에 선언한 제약 검사를 실행']])+call('DTO에 제약 어노테이션을 적는 것과 검사를 실행하는 것은 다릅니다.<br>검증 라이브러리 의존성도 프로젝트에 있어야 합니다.'),note='책 10장의 코드와 실제 build.gradle을 비교합니다. Spring Boot 프로젝트에는 spring-boot-starter-validation 의존성이 필요합니다. 수업 참고 소스의 jakarta.validation import와 사용 중인 Spring Boot 버전을 맞춥니다. @Min만으로 null을 거부한다고 설명하지 않습니다. 클래스 밖 서비스 메서드 검증의 @Validated 등은 오늘 필수가 아닙니다.')
add('검증 적용 준비','검증 라이브러리 설정',table([['확인할 곳','적용할 내용'],['build.gradle','spring-boot-starter-validation 의존성 추가'],['Gradle','변경한 의존성을 동기화한 뒤 프로젝트 빌드'],['import','jakarta.validation.Valid · jakarta.validation.constraints 사용']])+call('책의 검증 코드를 적용하기 전에 현재 프로젝트 설정을 확인합니다.'),note="Gradle dependencies에 implementation 'org.springframework.boot:spring-boot-starter-validation'을 추가하거나 이미 있는지 확인합니다. IDE의 Gradle 프로젝트 새로고침을 실행합니다. 기존 프로젝트의 Spring Boot 버전을 유지하며 Spring Boot 3·4의 jakarta.validation을 기준으로 설명합니다. 기존 7일 테스트와 주입/AOP 코드는 변경하지 않습니다. javax.validation 예제를 혼용하지 않습니다.")
add('예외 처리','실패가 발생하는 위치',table([['발생 위치','예외 처리에서 구분할 상황'],['Controller 실행 전','JSON 읽기 실패 · 요청 DTO 검증 실패'],['도메인·Service 실행 중','상품 규칙 위반 · 없는 상품 조회'],['예상하지 못한 처리 중','개발 오류나 외부 시스템 장애']])+call('Controller에 도착하지 않은 실패도 응답으로 정리해야 합니다.<br>입력 오류와 서버 오류를 같은 종류로 처리하지 않습니다.'),note='프레임워크의 일반적인 요청 DTO 검증 실패는 MethodArgumentNotValidException, JSON 읽기 실패는 HttpMessageNotReadableException으로 연결됩니다. 직접 메서드 매개변수에 제약을 두는 방법 등은 다른 검증 예외가 생길 수 있으므로 오늘 참고 코드의 범위를 명확히 합니다. 실제 예외명 암기보다 발생 위치와 처리 목적을 이해하게 합니다.')
add('교재 CH 10','전역 예외 핸들러',table([['구성 요소','오늘 코드에서의 역할'],['@RestControllerAdvice','Controller 관련 예외 처리를 한곳에 모으기'],['@ExceptionHandler','예외 종류에 맞는 상태·오류 본문 반환'],['오류 응답 본문','클라이언트가 이해할 수 있는 일정한 형식 사용']])+call('오늘 참고 형식은 message 필드입니다.<br>서버 내부 예외 정보 전체를 사용자용 메시지로 그대로 보내지 않습니다.'),note='교재의 전역 예외 핸들러 부분을 읽고 상품 없음은 404, 입력 관련 실패는 400으로 분류한 코드를 확인합니다. 이 매핑은 수업 예제의 설계이며 모든 IllegalArgumentException이 언제나 클라이언트 오류라는 일반 규칙은 아닙니다. 예상하지 못한 예외를 catch(Exception)으로 잡아 모두 400으로 응답하지 않습니다. 예외 상세는 서버에서 진단하고 응답에는 필요한 정보만 담습니다.')
add('QA 활동','QA 체크리스트 작성과 실행',steps('상품 API의 요구사항에서 확인할 항목 정리','사전 조건·입력·기대 결과·실제 결과·통과 여부 작성','직접 실행하고 발견한 문제 수정','다시 확인한 결과와 남은 문제를 README에 기록')+call('정상 동작·잘못된 입력·경계 조건·실패 시 데이터 유지를 포함합니다.<br>구체적인 입력값과 확인 순서는 직접 설계합니다.'),note='새 프로젝트를 만들지 않고 기존 product-api에서 짧게 수행합니다. 책의 검증과 예외 처리를 적용한 범위만 확인하며 정답 체크리스트를 배포하지 않습니다. Postman 또는 현재 사용 가능한 클라이언트를 이용합니다. 7일 단위·통합 테스트는 유지하되 새로운 테스트 코드 작성을 오늘 QA 활동의 필수 조건으로 만들지 않습니다. 상품 HTTP API 연결이 미완료라면 해당 범위를 먼저 마치고 실제 완료 수준을 기록합니다.')
add('개인 과제','위시리스트 유효성 검사',table([['입력·상황','지켜야 할 규칙'],['이름','null·빈 문자열·공백뿐인 이름 거부 · 앞뒤 공백 제거'],['가격','0 이상의 정수 · 무료 항목 0원 허용'],['예산·조회 id','음수 예산 거부 · 없는 id는 예외로 구분']])+call('기존 personal-project/의 검증을 유지하고 빠진 조건과 검사 위치를 보완합니다.<br>실패한 요청은 기존 데이터를 바꾸지 않아야 합니다.'),note='7일에 만든 위시리스트에 오늘 배운 검증 책임 분리를 적용하는 과제입니다. 이미 구현한 규칙을 지우거나 똑같이 다시 만들지 않습니다. Domain이 이름·가격을 지키고 Service가 예산과 존재 여부를 확인하도록 현재 코드를 점검해 누락된 부분을 보완합니다. 가격 0·예산 0 허용, 추천의 가격 정렬·동일 가격 등록 순서·최대 3개·원본 보존과 기존 테스트를 유지합니다. 새 프로젝트와 DB는 만들지 않습니다.')
add('개인 과제','검증 적용 범위와 제출',table([['항목','과제 내용'],['적용 범위','Domain·Service 검증 필수 · HTTP API가 있으면 요청 DTO와 실패 응답도 적용'],['QA·README','직접 체크리스트 작성·실행 · 검증 위치와 실제 결과 기록'],['Issue·PR 제목','[11/09][이름] 위시리스트 유효성 검사']])+call('기존 개인 Fork의 personal-project/에서 작업합니다. 새 HTTP API는 필수가 아닙니다.<br>공용 저장소에 이 과제의 Issue 1개·PR 1개로 코드와 README를 제출합니다.'),note='HTTP API가 이미 있는 경우에만 요청 DTO 이름에 @NotBlank, 가격은 Integer와 @NotNull·@Min(0), Controller 인자에 @Valid를 적용하고 적절한 400·404 응답을 연결합니다. HTTP가 없다면 Domain·Service에서 검증하며 어노테이션을 붙이는 것 자체를 완료 기준으로 삼지 않습니다. QA 항목은 정상·잘못된 입력·경계 조건·실패 시 데이터 보존을 고려해 교육생이 직접 설계합니다. README에는 검증을 맡긴 위치와 이유, 실행 결과·발견한 문제·수정 결과·남은 문제를 기록하고 기존 테스트를 유지합니다. 상품 API의 수업 중 QA 기록과 별개인 개인 과제 제출입니다. 기존 구현 브랜치에서 새 자율 이름의 브랜치를 만들고 개인 origin에 Push한 뒤 조직 원본 sesac-ddm-4-web/sesac-spring-boot-study의 main으로 PR을 올립니다. 이전 PR 링크와 이번 보완 범위를 적으며 리뷰 수정은 같은 브랜치에 Push합니다. 강사는 병합 없이 PR·Issue를 닫고 제출 브랜치를 보존합니다.')
add('시간이 남으면 · CH 11','데이터베이스 연동 도입',table([['읽을 곳','함께 볼 내용'],['1. DB를 사용하는 웹 애플리케이션','메모리 저장과 DB 저장의 차이'],['2. 데이터베이스 다뤄 보기','테이블·행·열·기본키와 간단한 SQL'],['다음 단계','상품 Repository가 DB에 저장·조회하도록 변경']])+call('오늘은 도입만 진행합니다. DB 연결과 전체 CRUD 구현은 별도 진도로 이어갑니다.'),note='발표와 MVC·검증 설명 후 시간이 남고 이해도가 충분할 때만 진행합니다. 프로세스 메모리는 재시작하면 초기화되고, DB 저장은 적절한 영구 저장 설정과 연결이 유지될 때 재시작 후 다시 읽을 수 있습니다. 모든 DB가 자동으로 영구 저장한다는 식으로 설명하지 않습니다. 교재 11장의 JDBC 접근과 이후 JPA 접근은 구분합니다. 오늘 JPA·Entity·N+1을 선행 강의하지 않습니다.')
